// ============================================
// FILTER COURSE EXPIRING EVENTS
// ============================================

const items = $input.all();
const expiringEvents = [];

for (const item of items) {
  const data = item.json;

  let event = data.event || data;
  if (typeof event === 'string') {
    try {
      event = JSON.parse(event);
    } catch (e) {
      continue;
    }
  }

  if (event.event === 'course.access.expiring' || event.type === 'course.access.expiring') {
    expiringEvents.push({
      json: {
        event_id: data.id || `course_exp_${Date.now()}`,
        event_type: 'course.access.expiring',
        guild_id: event.guild_id,
        user_id: event.data?.user_id || event.user_id,
        discord_id: event.data?.discord_id || event.discord_id,
        course_id: event.data?.course_id || event.course_id,
        course_name: event.data?.course_name || event.course_name || 'Formation',
        expires_at: event.data?.expires_at || event.expires_at,
        days_remaining: event.data?.days_remaining || 7,
        urgency: event.data?.urgency || 'normal',
        timestamp: event.timestamp || new Date().toISOString()
      }
    });
  }
}

return expiringEvents.length > 0 ? expiringEvents : [];

// ============================================
// PREPARE EXPIRATION EMBED
// ============================================

const data = $input.first().json;

const urgencyConfig = {
  critical: { color: 0xE74C3C, icon: '🚨', prefix: 'URGENT: ' },
  high: { color: 0xE67E22, icon: '⚠️', prefix: '' },
  normal: { color: 0xF1C40F, icon: '📅', prefix: '' }
};

const config = urgencyConfig[data.urgency] || urgencyConfig.normal;

const embed = {
  title: `${config.icon} ${config.prefix}Acces expire bientot`,
  description: `Ton acces a **${data.course_name}** expire dans ${data.days_remaining} jour(s).`,
  color: config.color,
  fields: [
    {
      name: 'Formation',
      value: data.course_name,
      inline: true
    },
    {
      name: 'Expire le',
      value: new Date(data.expires_at).toLocaleDateString('fr-FR'),
      inline: true
    }
  ],
  footer: { text: 'Pense a renouveler ton abonnement !' },
  timestamp: data.timestamp
};

return {
  type: 'dm',
  guild_id: data.guild_id,
  discord_id: data.discord_id,
  content: data.urgency === 'critical' ? `<@${data.discord_id}> 🚨` : null,
  embed: embed,
  notification_type: 'course_expiring',
  urgency: data.urgency,
  source: 'n8n:NOTIF-Course-Expiring',
  event_id: data.event_id,
  timestamp: new Date().toISOString()
};

